<?php
declare(strict_types=1);
require dirname(__DIR__).'/app/bootstrap.php';require __DIR__.'/discord-support.php';
if(PHP_SAPI!=='cli'||getenv('APP_ENV')!=='test'||getenv('DB_DATABASE')!=='levelingwiki_test')exit(1);
function towerCheck(bool $ok,string $label):void{if(!$ok)throw new RuntimeException($label);echo "OK tour : $label\n";}
$p=App\Services\Database::connect();seedDiscordRoles($p);
$anon=new HttpTestClient();towerCheck($anon->request('/tour-de-guilde')['status']===303,'authentification membre obligatoire');
$member=discordLogin('100000000000000901',['200000000000000001']);
$editor=discordLogin('100000000000000902',['200000000000000001','200000000000000002']);
$other=discordLogin('100000000000000903',['200000000000000001','200000000000000002']);
$admin=discordLogin('100000000000000904',['200000000000000001','200000000000000003']);
$uid=static function(string $discord)use($p):int{$q=$p->prepare('SELECT user_id FROM discord_identities WHERE discord_user_id=?');$q->execute([$discord]);return (int)$q->fetchColumn();};
$editorId=$uid('100000000000000902');$otherId=$uid('100000000000000903');$memberId=$uid('100000000000000901');
$post=static fn(HttpTestClient $c,string $path,array $d)=>$c->request($path,['csrf'=>$c->token('/profil'),...$d]);
$repo=new App\Models\GuildDivisionRepository($p);
towerCheck($repo->all()===[],'migration sans divisions fictives');
$r=$member->request('/tour-de-guilde');towerCheck($r['status']===200&&str_contains($r['body'],'Aucune division active'),'état vide exploitable');
towerCheck(str_contains($r['body'],'href="/tour-de-guilde"')&&!str_contains($r['body'],'tower-scenario')&&!str_contains($r['body'],'division-v1'),'navigation réelle sans scénarios ni divisions fictives');
towerCheck($member->request('/admin/tour-de-guilde')['status']===403,'membre sans rôle de gestion refusé');
$draft=['name'=>'Division test <script>','short_name'=>'T1','description'=>'Description <b>test</b>','color'=>'#AA77CC','level'=>'43','archived'=>'0','master_ids'=>[$editorId,$otherId]];
towerCheck($post($editor,'/admin/tour-de-guilde/save',$draft)['status']===403,'éditeur ne peut pas créer');
towerCheck($admin->request('/admin/tour-de-guilde/save',['csrf'=>'bad',...$draft])['status']===403,'CSRF création');
$r=$post($admin,'/admin/tour-de-guilde/save',$draft);towerCheck($r['status']===303,'création administrateur');parse_str(parse_url($r['location'],PHP_URL_QUERY),$params);$id=(int)$params['division'];
$row=$repo->find($id);towerCheck($row['name']===$draft['name']&&(int)$row['level']===43,'persistance MariaDB');
towerCheck($repo->masterIds($id)===[$editorId,$otherId],'plusieurs Guild Masters associés');
towerCheck(count($repo->history($id))===1,'historique de création');
$r=$member->request('/tour-de-guilde');towerCheck(str_contains($r['body'],'Division test &lt;script&gt;')&&!str_contains($r['body'],'Division test <script>'),'échappement des noms');
towerCheck(str_contains($r['body'],'#division-guild-'.$id)&&str_contains($r['body'],'data-division-color="#AA77CC"'),'raccourci et couleur réels');
$second=$draft;$second['name']='Deuxième division';$second['master_ids']=[];
$r=$post($admin,'/admin/tour-de-guilde/save',$second);parse_str(parse_url($r['location'],PHP_URL_QUERY),$params);$secondId=(int)$params['division'];
towerCheck($post($editor,'/admin/tour-de-guilde/level',['id'=>$secondId,'version'=>1,'level'=>50])['status']===403,'ID de division étrangère refusé');
towerCheck($editor->request('/admin/tour-de-guilde?division='.$secondId)['status']===403,'historique étranger interdit');
towerCheck($post($editor,'/admin/tour-de-guilde/level',['id'=>$id,'version'=>1,'level'=>44,'master_ids'=>[$editorId]])['status']===422,'escalade de permissions par champ interdit refusée');
foreach(['0','-1','1.5','1e2','4294967296',''] as $invalid)towerCheck($post($editor,'/admin/tour-de-guilde/level',['id'=>$id,'version'=>1,'level'=>$invalid])['status']===422,'niveau invalide refusé : '.$invalid);
$r=$post($editor,'/admin/tour-de-guilde/level',['id'=>$id,'version'=>1,'level'=>135]);towerCheck($r['status']===303,'Guild Master modifie son niveau');
towerCheck((int)$repo->find($id)['level']===135&&count($repo->history($id))===2,'niveau et historique atomiques');
towerCheck($post($other,'/admin/tour-de-guilde/level',['id'=>$id,'version'=>1,'level'=>140])['status']===409,'modification concurrente périmée refusée');
towerCheck((int)$repo->find($id)['level']===135,'conflit sans écrasement');
$r=$member->request('/tour-de-guilde');towerCheck(str_contains($r['body'],'135')&&str_contains($r['body'],'92 niveaux derrière'),'niveau et écarts recalculés');
$change=$draft+['id'=>$id,'version'=>2];$change['level']='135';$change['master_ids']=[$otherId];
towerCheck($post($admin,'/admin/tour-de-guilde/save',$change)['status']===303,'retrait d’un responsable');
towerCheck($post($editor,'/admin/tour-de-guilde/level',['id'=>$id,'version'=>3,'level'=>150])['status']===403,'retrait immédiatement effectif');
$bad=$change;$bad['version']=3;$bad['master_ids']=[$memberId];
towerCheck($post($admin,'/admin/tour-de-guilde/save',$bad)['status']===422,'membre non editor/admin exclu des responsables');
towerCheck((int)$repo->find($id)['version']===3&&$repo->masterIds($id)===[$otherId],'validation échouée : transaction intacte');
$change['version']=3;$change['archived']='1';
towerCheck($post($admin,'/admin/tour-de-guilde/save',$change)['status']===303,'archivage administrateur');
towerCheck($post($other,'/admin/tour-de-guilde/level',['id'=>$id,'version'=>4,'level'=>150])['status']===409,'progression archivée interdite');
towerCheck(!str_contains($member->request('/tour-de-guilde')['body'],'#division-guild-'.$id),'division archivée retirée de la tour');
towerCheck(count($repo->history($id))===2,'historique conservé après archivage');
$change['version']=4;$change['archived']='0';
towerCheck($post($admin,'/admin/tour-de-guilde/save',$change)['status']===303,'restauration sans perte');
// Discord role loss invalidates the scope at the daily verification.
mockDiscord(['user'=>['id'=>'100000000000000903','roles'=>['200000000000000001']]]);
expireDiscordCache($other);
towerCheck($post($other,'/admin/tour-de-guilde/level',['id'=>$id,'version'=>5,'level'=>160])['status']===403,'rôle editor retiré : écriture refusée');
$q=$p->prepare("SELECT COUNT(*) FROM audit_logs WHERE entity_type='guild_division' AND entity_id=? AND new_values LIKE '%master_ids%'");$q->execute([$id]);towerCheck((int)$q->fetchColumn()>=3,'associations et métadonnées auditées');
towerCheck($member->request('/tour-de-guilde',['csrf'=>$member->token('/profil')])['status']===405,'page métier en lecture seule');
